constexpr uint16_t kMaxWorldX =
    (LEVEL_1_1_LENGTH_COLUMNS * kBlockPx > kScreenWidthPx)
        ? static_cast<uint16_t>(LEVEL_1_1_LENGTH_COLUMNS * kBlockPx - kScreenWidthPx)
        : uint16_t{0};

// tracks the rom's camera position by driving it exactly as main.c does: 2px per frame, one d-pad
// direction per axis, clamped the same way terrain.c clamps. the test never reads rom-private state.
struct Camera {
    uint16_t x = 0;
    uint8_t y = 0;

    void goto_xy(gb::Gameboy& gameboy, uint16_t target_x, uint8_t target_y) {
        while (x != target_x || y != target_y) {
            const bool right = x < target_x;
            const bool left = x > target_x;
            const bool down = y < target_y;
            const bool up = y > target_y;
            gameboy.set_button(gb::Button::Right, right);
            gameboy.set_button(gb::Button::Left, left);
            gameboy.set_button(gb::Button::Down, down);
            gameboy.set_button(gb::Button::Up, up);
            gameboy.run_frame();
            if (right) {
                x = static_cast<uint16_t>(x + 2);
            }
            if (left) {
                x = static_cast<uint16_t>(x - 2);
            }
            if (down) {
                y = static_cast<uint8_t>(y + 2);
            }
            if (up) {
                y = static_cast<uint8_t>(y - 2);
            }
        }
        gameboy.set_button(gb::Button::Right, false);
        gameboy.set_button(gb::Button::Left, false);
        gameboy.set_button(gb::Button::Down, false);
        gameboy.set_button(gb::Button::Up, false);
    }
};

// scy that brings block row `row` fully into the 144px window (see terrain.c's viewport math)
uint8_t scy_for_row(uint8_t row) {
    const uint16_t px = static_cast<uint16_t>(static_cast<uint16_t>(row) * kBlockPx);
    return static_cast<uint8_t>(px < kScyMax ? px : kScyMax);
}

// scx that brings block column `column` fully into the 160px window, clamped to the level's range
uint16_t scx_for_column(uint16_t column) {
    const uint16_t px = static_cast<uint16_t>(column * kBlockPx);
    return px < kMaxWorldX ? px : kMaxWorldX;
}

// the tile id at the world block (column, row)'s top-left 8x8 cell, given the camera sits at
// (cam_x, cam_y); the caller must have parked the camera so the block is actually on screen
uint8_t block_tile(const gb::Gameboy& gameboy, uint16_t column, uint8_t row, uint16_t cam_x, uint8_t cam_y) {
    const uint32_t screen_x = static_cast<uint32_t>(column) * kBlockPx - cam_x;
    const uint32_t screen_y = static_cast<uint32_t>(row) * kBlockPx - cam_y;
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const uint16_t id = ids[(screen_y + 3) * gb::kLcdWidth + screen_x + 3];
    return static_cast<uint8_t>(id & 0xFFu);
}

// pinned bg tile family ranges per claude-docs/milestones/18-smbd.md's test/tile-id contract and
// the id map recorded in games/mario/src/assets.h
bool tile_in_kind_family(uint8_t tile, uint8_t kind) {
    switch (kind) {
    case kBlockEmpty:
        return tile == 0x00;
    case kBlockGround:
    case kBlockHard:
    case kBlockStair:
        return tile >= 0xA0 && tile <= 0xA3;
    case kBlockBrick:
        return tile >= 0xA4 && tile <= 0xA7;
    case kBlockQuestion:
        return tile >= 0xA8 && tile <= 0xAB;
    case kBlockPipeTl:
    case kBlockPipeTr:
    case kBlockPipeBodyL:
    case kBlockPipeBodyR:
        return tile >= 0xB0 && tile <= 0xB7;
    case kBlockFlagPole:
    case kBlockCastle:
        return tile >= 0xB8 && tile <= 0xBB;
    case kBlockSpent:
        return tile >= kTileSpentLo && tile <= kTileSpentHi;
    case kBlockCoin:
        return tile >= kTileWorldCoinLo && tile <= kTileWorldCoinHi;
    default:
        return false;
    }
}

// every family a terrain cell may legitimately render as: sky/ground/brick/question/hard/pipe/
// flag/castle share the 0xa0-0xbf block, and the font glyphs cover sky's reused space tile
bool is_known_terrain_family(uint8_t tile) {
    return tile <= 0x5F || (tile >= 0xA0 && tile <= 0xBF);
}

// --- sub-milestone 3: the player ---------------------------------------------------------------

// mirrors of games/mario/src/mario.h's player geometry, the same way kBlockPx above mirrors it
constexpr uint8_t kMarioFirstTile = 0xE0;
constexpr uint8_t kMarioTilesPerFrame = 4;
constexpr uint8_t kMarioFrameCount = 6;
constexpr uint8_t kMarioLastTile = kMarioFirstTile + kMarioFrameCount * kMarioTilesPerFrame - 1;
constexpr int kFrameIdle = 0;
constexpr int kFrameWalk0 = 1;
constexpr int kFrameWalk2 = 3;
constexpr int kFrameSkid = 4;
constexpr int kFrameJump = 5;
constexpr int kPlayerBoxPx = 16;
// the art keeps column 0 and column 15 of the 16px box transparent, so lit pixels sit one in
constexpr int kMarioArtInset = 1;
constexpr int kPlayScy = kScyMax;

// mario's world y while standing on the bible's start cell, in screen px (scy is pinned in play)
constexpr int kStandTop = static_cast<int>(LEVEL_1_1_START_ROW) * kBlockPx - kPlayerBoxPx - kPlayScy;

struct Mario {
    int left = 0;
    int right = 0;
    int top = 0;
    int frame = -1;
    bool found = false;
};

Mario mario_at(const gb::Gameboy& gameboy) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    Mario m;
    for (size_t i = 0; i < ids.size(); ++i) {
        if ((ids[i] & 0x100u) == 0) {
            continue;
        }
        const uint8_t tile = static_cast<uint8_t>(ids[i]);
        if (tile < kMarioFirstTile || tile > kMarioLastTile) {
            continue;
        }
        const int x = static_cast<int>(i % gb::kLcdWidth);
        const int y = static_cast<int>(i / gb::kLcdWidth);
        if (!m.found || x < m.left) {
            m.left = x;
        }
        if (!m.found || x > m.right) {
            m.right = x;
        }
        if (!m.found || y < m.top) {
            m.top = y;
        }
        m.frame = (tile - kMarioFirstTile) / kMarioTilesPerFrame;
        m.found = true;
    }
    return m;
}

// row 3 of the ground-top tile carries one dark speck every 4 px (see kGroundTiles in assets.c),
// so this scanline's first color-0 ground pixel gives the camera's position mod 4
constexpr int kGroundPhaseRow = 13 * kBlockPx + 3 - kPlayScy;

int ground_phase(const gb::Gameboy& gameboy) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const std::span<const uint8_t> fb = gameboy.framebuffer();
    for (int x = 0; x < static_cast<int>(gb::kLcdWidth); ++x) {
        const size_t i = static_cast<size_t>(kGroundPhaseRow) * gb::kLcdWidth + static_cast<size_t>(x);
        if ((ids[i] & 0x100u) != 0) {
            continue;
        }
        if (static_cast<uint8_t>(ids[i]) == 0xA0 && fb[i] == 0) {
            return x % 4;
        }
    }
    return -1;
}

// the rom never exposes mario's world x, so the test reconstructs it: once the camera follows, his
// screen x is pinned and the whole displacement shows up in the camera's 4px phase; before that the
// camera is parked and it all shows up in his screen x. no step ever exceeds the 2.5 px/frame run
// cap, so the phase difference is unambiguous mod 4.
struct WorldTracker {
    int phase = 0;
    int screen = 0;

    void sync(const gb::Gameboy& gameboy, const Mario& m) {
        phase = ground_phase(gameboy);
        screen = m.left;
    }

    int step(const gb::Gameboy& gameboy, const Mario& m) {
        const int next = ground_phase(gameboy);
        const int cam = ((phase - next) % 4 + 4) % 4;
        const int moved = cam + (m.left - screen);
        phase = next;
        screen = m.left;
        return moved;
    }
};

// the bible's tables, generated straight from physics.json - the same header player.c reads
constexpr int8_t kJumpSpeed[kMarioJumpTierCount] = kMarioJumpSpeedInit;
constexpr uint8_t kGravityRise[kMarioJumpTierCount] = kMarioGravityRiseInit;
constexpr uint8_t kGravityFall[kMarioJumpTierCount] = kMarioGravityFallInit;

// host-side twin of player.c's vertical step: whole-px speed, a 1/256-px accumulator gravity feeds,
// and the bible's hold-a rule. tier 0 because every arc here starts from a standstill.
struct JumpSim {
    int y = kStandTop;
    int8_t speed = 0;
    uint8_t accum = 0;
    int origin = kStandTop;
    bool grounded = true;
    bool a_prev = false;

    void step(bool a) {
        if (grounded && a && !a_prev) {
            speed = kJumpSpeed[0];
            accum = 0;
            origin = y;
            grounded = false;
        }
        uint8_t force = kGravityFall[0];
        if (speed < 0 && ((a && a_prev) || (origin - y) < kMarioMinRisePx)) {
            force = kGravityRise[0];
        }
        const unsigned sum = static_cast<unsigned>(accum) + force;
        accum = static_cast<uint8_t>(sum);
        if (sum > 0xFFu) {
            speed = static_cast<int8_t>(speed + 1);
            if (speed > kMarioMaxFallPx) {
                speed = kMarioMaxFallPx;
            }
        }
        y += speed;
        // the start cell's floor is flat, so landing is one clamp back onto the standing row
        if (speed >= 0 && y >= kStandTop) {
            y = kStandTop;
            speed = 0;
            accum = 0;
            grounded = true;
        }
        a_prev = a;
    }
};

// drives one jump and returns mario's sprite top per frame. the rom reads the buttons set before
// run_frame i on its own frame i, but that frame is only scanned out one frame later, which is
// what the lag the callers measure accounts for.
std::vector<int> jump_tops(gb::Gameboy& gameboy, int hold_frames, int frames) {
    std::vector<int> tops;
    tops.reserve(static_cast<size_t>(frames));
    for (int i = 0; i < frames; ++i) {
        gameboy.set_button(gb::Button::A, i < hold_frames);
        gameboy.run_frame();
        const Mario m = mario_at(gameboy);
        REQUIRE(m.found);
        tops.push_back(m.top);
    }
    gameboy.set_button(gb::Button::A, false);
    return tops;
}

// the first frame mario's sprite actually moves; everything before it is the rom's scanout lag
int first_move(const std::vector<int>& tops) {
    for (size_t i = 0; i < tops.size(); ++i) {
        if (tops[i] != kStandTop) {
            return static_cast<int>(i);
        }
    }
    return -1;
}

// holds a direction (plus b to run) and returns the world px covered over the whole window
int travel(gb::Gameboy& gameboy, gb::Button dir, bool run_button, int frames) {
    WorldTracker tracker;
    tracker.sync(gameboy, mario_at(gameboy));
    gameboy.set_button(dir, true);
    gameboy.set_button(gb::Button::B, run_button);
    int total = 0;
    for (int i = 0; i < frames; ++i) {
        gameboy.run_frame();
        total += tracker.step(gameboy, mario_at(gameboy));
    }
    return total;
}

// the leftmost screen x carrying a bg pixel of the given tile family on mario's own rows, or -1
int face_of(const gb::Gameboy& gameboy, const Mario& m, uint8_t lo, uint8_t hi) {
    const std::span<const uint16_t> ids = gameboy.framebuffer_tiles();
    const int bottom = std::min(m.top + kPlayerBoxPx, static_cast<int>(gb::kLcdHeight));
    for (int x = 0; x < static_cast<int>(gb::kLcdWidth); ++x) {
        for (int y = std::max(m.top, 0); y < bottom; ++y) {
            const size_t i = static_cast<size_t>(y) * gb::kLcdWidth + static_cast<size_t>(x);
            if ((ids[i] & 0x100u) != 0) {
                continue;
            }
            const uint8_t tile = static_cast<uint8_t>(ids[i]);
            if (tile >= lo && tile <= hi) {
                return x;
            }
        }
    }
    return -1;
}

int pipe_face(const gb::Gameboy& gameboy, const Mario& m) {
    return face_of(gameboy, m, 0xB0, 0xB7);
}

int pole_face(const gb::Gameboy& gameboy, const Mario& m) {
    return face_of(gameboy, m, 0xB8, 0xBF);
}

// the level's first pipe, from the compiler's own probes rather than the bible's json
uint16_t first_pipe_column() {
    for (const auto& probe : kLevel11Probes) {
        if (probe.kind == kBlockPipeTl) {
            return probe.column;
        }
    }
    return 0;
}

// the level's first pit, taken from the compiler's own probes rather than the bible's json
uint16_t first_gap_column() {
    for (const auto& probe : kLevel11Probes) {
        if (probe.kind == kBlockEmpty && probe.row == 13) {
            return probe.column;
        }
    }
    return 0;
}

